#!/usr/bin/env python3
import datetime,hashlib,json,shutil,subprocess,tarfile
from pathlib import Path
O=Path(__file__).resolve().parent;R=O.parents[1];P=R/'verification/hosted-identity-startup-implementation';state=json.loads((O/'state.json').read_text());S=Path(state['scratch'])
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,v):(O/n).write_text(json.dumps(v,indent=2)+'\n')
producer=json.loads((P/'receipt.json').read_text());m=json.loads((P/'tested-source-manifest.json').read_text());sv=json.loads((O/'source-verification.json').read_text())
# Recheck all frozen inputs at close; preserve every producer packet byte.
assert all(sha(P/path)==h for path,h in producer['bindings'].items())
assert all(sha(S/path)==h for path,h in m['files'].items())
assert sha(P/'implementation.patch')==producer['patchSHA256']==sv['patchSHA256']
assert 'Result: 85 passed, 2 skipped' in (O/'host-suite/tests.log').read_text()
assert 'Result: 87 passed' in (O/'linux-tests.log').read_text()
assert 'Result: 8/9 passed' in (O/'adversarial.log').read_text()
assert 'Result: 8/9 passed' in (O/'linux-adversarial.log').read_text()
assert 'Failed: 4 tests' in (O/'endpoint-regression.log').read_text()
host=json.loads((O/'host-suite/receipt.json').read_text());linux=json.loads((O/'linux-receipt.json').read_text());assert host['status']=='passed';assert linux['status']=='normal-suite-passed-adversarial-finding';assert all(linux['cleanup'].values());assert all(host['cleanup'].values())
# The original source remains bit-for-bit frozen, with only review-owned tests added.
review={path:sha(S/path) for path in m['files']}
for name in ['review_startup_adversarial_test.exs','endpoint_regression_test.exs']:
 path='hosted/test/mixer_hosted/identity/'+name;assert sha(S/path)==sha(O/name);review[path]=sha(S/path)
save('review-source-manifest.json',{'frozenCandidateDigest':producer['testedSourceDigest'],'files':review,'digest':hashlib.sha256(json.dumps(review,sort_keys=True,separators=(',',':')).encode()).hexdigest(),'additionalInputs':['review_startup_adversarial_test.exs','endpoint_regression_test.exs','endpoint_probe.exs']})
with tarfile.open(O/'review-source.tar.gz','w:gz') as t:
 for path in review:t.add(S/path,arcname=path,recursive=False)
# Verify Mac collector database is no longer live and only remove owned scratch.
pgstart=next(c for c in host['commands'] if c['label']=='postgres-start');pgdata=Path(pgstart['argv'][pgstart['argv'].index('-D')+1]);assert not pgdata.parent.exists()
shutil.rmtree(S);assert not S.exists()
cleanup={'ownedMacSourceScratchRemoved':not S.exists(),'ownedMacPostgresStopped':host['cleanup']['postgres_stopped'],'ownedMacPostgresScratchRemoved':host['cleanup']['scratch_removed'],'ownedLinux':linux['cleanup'],'scope':'Only unique review-owned source, PostgreSQL, containers and fixtures. Other projects preserved. No native, physical or UI activity.'};save('cleanup.json',cleanup)
# Bind original source defects and related strict resolver/DB hostname findings without broadening scope.
save('findings.json',{'status':'correction-required','findings':[{'id':'IR-F01','priority':2,'title':'Reject endpoint newline before startup accepts configuration','source':'hosted/lib/mixer_hosted/identity/manifest.ex','lines':[56,63],'sourceSHA256':m['files']['hosted/lib/mixer_hosted/identity/manifest.ex'],'origin':'inherited accepted Manifest validator; exposed through new StartupConfig operator JSON','inputs':[{'field':'jwks_endpoint.host','value':'keys.independent.invalid\n','actual':'StartupConfig accepted and Manifest.validate returned {:ok, map}'},{'field':'jwks_endpoint.path','value':'/keys\n','actual':'StartupConfig accepted and Manifest.validate returned {:ok, map}'}],'expected':'invalid identity startup: configuration / {:error, :invalid_manifest}','reason':'Regex $ accepts a final newline; each host label and path must validate the complete string.','correction':'Use strict \\A and \\z anchors in both existing Manifest expressions and add direct Manifest/StartupConfig rejection regressions plus valid controls.','networkConsequenceClaimed':False,'evidence':['endpoint-probe.log','endpoint-regression.log','adversarial.log','linux-adversarial.log']}],'relatedChecks':{'RuntimeConfigDatabaseHostname':'already uses strict \\A...\\z; no same defect','StartupConfigResolver':'strict parse/format round trip; trailing LF, whitespace, zones, alternate numeric forms rejected','unrelatedHTTPResponseRegexes':'not modified or swept into this bounded endpoint configuration review'}})
outputs={str(p.relative_to(O)):sha(p) for p in sorted(O.rglob('*')) if p.is_file() and p.name!='receipt.json'}
receipt={'schema':1,'status':'correction-required-original-candidate-frozen','observedUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'hosted_identity_startup_independent_review','documentation':'docs/hosted-identity-startup-review.md','documentationSHA256':sha(R/'docs/hosted-identity-startup-review.md'),'frozenProducerReceiptSHA256':sha(P/'receipt.json'),'currentAcceptedRevisionAtReconstruction':sv['currentRevision'],'producerSourceRevision':producer['sourceRevision'],'patchSHA256':producer['patchSHA256'],'frozenSourceDigest':producer['testedSourceDigest'],'dependencyDigest':producer['dependencyDigest'],'producerBoundOutputCount':197,'overlayFiles':producer['overlayFiles'],'sourceReconstruction':'current accepted source + frozen patch equals every frozen manifest/archive entry; no producer/live source mutation','reviewSourceDigest':json.loads((O/'review-source-manifest.json').read_text())['digest'],'results':{'macOSNormal':{'passed':85,'skipped':2,'scope':'Linux-only skips'},'linuxNormal':{'passed':87,'skipped':0},'productionRelease':'built','missingRuntimeConfig':'expected exit 1 observed','testOnlyProductionExports':'excluded','macOSIndependentAdversarial':{'passed':8,'failed':1,'failure':'IR02 / IR-F01 host LF'},'linuxIndependentAdversarial':{'passed':8,'failed':1,'failure':'IR02 / IR-F01 host LF'},'minimalEndpointRegressions':{'failed':4,'scope':'expected rejection fails for direct Manifest and StartupConfig host/path LF'}},'cases':{'IS01':'observed','IS02':'correction-required IR-F01; other bounds/conversion/CA/resolver checks observed','IS03':'observed actual Application/Endpoint/PostgreSQL','IS04':'observed isolated production DNS53+HTTPS443/public ConfiguredVerifier cold admission','IS05':'observed actual lifecycle/lease/inflight shutdown','IS06':'observed normal suites/release/source bindings; adversarial failure explicitly retained'},'finding':'IR-F01','recommendation':'Apply bounded Manifest strict-anchor correction in a separate packet, add direct Manifest+StartupConfig regressions, and validate amended source before root acceptance. No acceptance of future packet implied.','failedAttempts':['adversarial.log','linux-adversarial.log','endpoint-regression.log'],'limitations':['Development slice; no GA acceptance.','Synthetic loopback PostgreSQL has no TLS; production database TLS is configuration evidence.','Synthetic CA/DNS/TLS and signed identity; no real provider contacted.','No authenticated HTTP, membership, permission, provider selection/discovery or durable registry.','No Neon/Cloudflare operational, FieldLog published-package dogfood, native/physical or customer qualification.','No commit/push, production publication, credentials or unrelated-process mutation.'],'cleanup':cleanup,'bindings':outputs}
save('receipt.json',receipt)
print(json.dumps({'status':receipt['status'],'bindings':len(outputs),'patchSHA256':receipt['patchSHA256'],'sourceDigest':receipt['frozenSourceDigest'],'finding':'IR-F01','scratchRemoved':not S.exists()}))
